/**
 * Вторые сцены обычных миссий (владелец 2026-11-02: «все обычные миссии хотя бы по 10 минут с интересными диалогами»). Часть A — 9 миссий.
 * Шаги дописываются В КОНЕЦ миссии (начатые прохождения не сбиваются: номера прежних шагов те же). Только `choice` и `build` —
 * им не нужен звук (новые реплики ещё не озвучены, генерация — только из админки). Подключение — `mission-scenes.ts`.
 */
import type { I18n } from '@polski-go/shared';
import { t } from './builders';
import type { MissionLine, MissionOption, MissionStep } from './missions';

export type MissionScene = { goal: I18n; steps: MissionStep[] };

export const npc = (pl: string, uk: string, ru: string, en: string): MissionLine => ({ who: 'npc', pl, tr: t(uk, ru, en) });
export const narr = (pl: string, uk: string, ru: string, en: string): MissionLine => ({ who: 'narrator', pl, tr: t(uk, ru, en) });
export const P = (pl: string, ok = false, why?: I18n): MissionOption => ({ pl, ok, why });
export const T = (text: I18n, ok = false, why?: I18n): MissionOption => ({ text, ok, why });
export const ch = (id: string, line: MissionLine | undefined, task: I18n, options: MissionOption[], hint: I18n, explain: I18n): MissionStep => ({ id, kind: 'choice', line, task, options, hint, explain });
export const bd = (id: string, line: MissionLine | undefined, task: I18n, answer: string, extra: string[], hint: I18n, explain: I18n, accept?: string[]): MissionStep => ({
  id, kind: 'build', line, task, answer, extra, hint, explain, ...(accept ? { accept } : {}),
});
const ANSWER = t('Відповідай.', 'Ответь.', 'Answer.');
const UNDERSTAND = t('Що це означає?', 'Что это значит?', 'What does it mean?');

